/* Simple Node.js / TypeScript-style example illustrating append, optimistic concurrency, and replay */

// Types
type Event = { type: string; payload: any; metadata?: any };

type StoredEvent = { streamId: string; seq: number; event: Event; timestamp: number };

// Mock event store API
const eventStore = {
  async append(streamId: string, expectedVersion: number | null, events: Event[]): Promise<number> {
    // Pseudocode: check expectedVersion; assign seq numbers; persist atomically
    // Throw on version mismatch (optimistic concurrency)
    // Return new version
  },
  async readStream(streamId: string): Promise<StoredEvent[]> {
    // Return events ordered by seq
    return [];
  }
};

// Aggregate example (Account)
class Account {
  balance = 0;
  apply(e: Event) {
    switch (e.type) {
      case 'MoneyCredited': this.balance += e.payload.amount; break;
      case 'MoneyDebited': this.balance -= e.payload.amount; break;
    }
  }
  static async load(streamId: string): Promise<Account> {
    const events = await eventStore.readStream(streamId);
    const a = new Account();
    for (const se of events) a.apply(se.event);
    return a;
  }
}

// Command handling example
async function handleTransfer(fromId: string, toId: string, amount: number) {
  const from = await Account.load(fromId);
  if (from.balance < amount) throw new Error('Insufficient funds');

  // Create events
  const debit: Event = { type: 'MoneyDebited', payload: { amount } };
  const credit: Event = { type: 'MoneyCredited', payload: { amount } };

  // Append with optimistic concurrency: expectedVersion could be last seq read
  await eventStore.append(fromId, /*expectedVersion*/ null, [debit]);
  await eventStore.append(toId, /*expectedVersion*/ null, [credit]);
}
